const DICTS = { en, hi, mr };
const LangCtx = createContext({ lang: 'en', setLang: () => {}, t: (k) => k });

export function LanguageProvider({ children }) {
  const [lang, setLangState] = useState(() => localStorage.getItem('ragnosis_lang') || 'en');
  const setLang = (l) => { localStorage.setItem('ragnosis_lang', l); setLangState(l); };
  const t = (key) => DICTS[lang]?.[key] ?? DICTS.en[key] ?? key;
  return <LangCtx.Provider value={{ lang, setLang, t }}>{children}</LangCtx.Provider>;
}

export const useLang = () => useContext(LangCtx);

export function LangSwitch({ style }) {
  const { lang, setLang } = useLang();
  return (
    <select className="select" value={lang} onChange={(e) => setLang(e.target.value)}
      aria-label="Language" style={{ width: 'auto', minHeight: 38, padding: '6px 32px 6px 12px', ...style }}>
      {LANGUAGES.map((l) => <option key={l.code} value={l.code}>{l.label}</option>)}
    </select>
  );
}
